-- Foto de Makarena y logotipos de Transportes FCA e Ibis Restaurant (11-11-2026).
-- Ejecutar una vez en el editor SQL de Supabase (proyecto BKO). Fusiona solo los campos modificados.
begin;

-- Equipo: fotografía de Makarena (texto, cargo y especialidades se mantienen).
update public.bko_content set data = data || '{"image":"assets/personas/makarena.jpeg","imageAlt":"Retrato de Makarena Andrea Ponce Villarroel"}'::jsonb where id='makarena-andrea-ponce-villarroel';

-- Transportes FCA: logotipo entregado. El trigger revoca la verificación al cambiar el archivo, por eso se confirma en un segundo paso.
update public.bko_clients set logo_local_path='assets/clientes/transportes-fca.jpeg', logo_storage_path='', logo_width=1280, logo_height=1280, logo_background='white' where slug='transportes-fca';
update public.bko_clients set logo_source='Entregado por el responsable del sitio (11-11-2026)', logo_verified=true, logo_authorized=true, verification_status='verified', active=true, published=true, relation_authorized=true, logo_authorization_reference='Logotipo entregado por el responsable del sitio el 11-11-2026 para su publicación.' where slug='transportes-fca';

-- Nuevo cliente: Ibis Restaurant (Puerto Varas).
insert into public.bko_clients(slug,name,original_name,website_url,website_original,website_verified,logo_local_path,logo_storage_path,logo_verified,logo_authorized,logo_source,logo_source_original,logo_status_original,verification_status,observations,sector,sector_source,description,sort_order,active,published,featured,relation_authorized,authorization_reference,logo_authorization_reference,original_row,logo_width,logo_height,logo_background) select slug,name,original_name,website_url,website_original,website_verified,logo_local_path,logo_storage_path,logo_verified,logo_authorized,logo_source,logo_source_original,logo_status_original,verification_status,observations,sector,sector_source,description,sort_order,active,published,featured,relation_authorized,authorization_reference,logo_authorization_reference,original_row,logo_width,logo_height,logo_background from jsonb_populate_record(null::public.bko_clients,'{"slug":"ibis-restaurant","name":"Ibis Restaurant","original_name":"Ibis Restaurant","website_url":"https://ibisrest.cl/","website_original":"https://ibisrest.cl/","website_verified":true,"logo_local_path":"assets/clientes/ibis-restaurant.png","logo_storage_path":"","logo_verified":true,"logo_authorized":true,"logo_source":"https://ibisrest.cl/wp-content/uploads/2023/10/LOGO-IBIS3.png","logo_source_original":"https://ibisrest.cl/","logo_status_original":"Logotipo original de la cabecera del sitio oficial","verification_status":"verified","observations":"Cliente agregado por instrucción del responsable del sitio (11-11-2026). Logotipo oficial descargado sin modificaciones desde su sitio.","sector":"turismo","sector_source":"https://ibisrest.cl/","description":"Restaurante de pescados y mariscos en Puerto Varas, frente al lago Llanquihue.","sort_order":250,"active":true,"published":true,"featured":false,"relation_authorized":true,"authorization_reference":"Instrucción del responsable del sitio, 11-11-2026: agregar https://ibisrest.cl/ como nuevo cliente.","logo_authorization_reference":"Instrucción del responsable del sitio de mostrar los logotipos de las empresas asociadas.","original_row":"https://ibisrest.cl/, nuevo cliente","logo_width":150,"logo_height":114,"logo_background":"white"}'::jsonb) on conflict(slug) do nothing;

commit;
